insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id from jsonb_to_recordset($bank$[{"id":"che-pe-208","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Beryllium and magnesium have unfavourable (near-zero or positive) electron gain enthalpies because they possess","options":["half-filled 2p sets","filled ns² subshells","incomplete 1s shells","seven valence electrons"],"answer_index":1,"explanation":"The extra electron would have to enter a higher np orbital against a closed s pair.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electron-gain"},{"id":"che-pe-209","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Among carbon, nitrogen, oxygen and fluorine, the most negative electron gain enthalpy is that of","options":["carbon","nitrogen","oxygen","fluorine"],"answer_index":3,"explanation":"Fluorine is one electron short of neon and, despite the F/Cl anomaly, is still the most exothermic of this period-2 set.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electron-gain"},{"id":"che-pe-210","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Chlorine outruns fluorine in electron gain enthalpy because the incoming electron enters a larger 3p orbital with less repulsion, even though fluorine has the","options":["lower electronegativity","higher electronegativity and higher Zeff","greater number of shells","smaller nuclear charge"],"answer_index":1,"explanation":"Two trends compete: F is smaller and more electronegative, yet inter-electronic repulsion in the compact 2p cloud makes ΔegH(F) less negative than ΔegH(Cl).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"electron-gain"},{"id":"che-pe-211","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Electronegativity is the tendency of an atom in a chemical bond to attract the","options":["nucleus of the other atom","shared electron pair towards itself","entire molecule into the lattice","neutrons of the partner"],"answer_index":1,"explanation":"It is a bonded-atom property, not an isolated-atom energy.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electronegativity"},{"id":"che-pe-212","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The most widely used numerical scale of electronegativity is the","options":["Mulliken scale only","Pauling scale","Celsius scale","Rydberg scale"],"answer_index":1,"explanation":"Pauling assigned fluorine the value 4.0 and built the rest of the scale from bond-energy data.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electronegativity"},{"id":"che-pe-213","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Fluorine is the most electronegative element, with a Pauling value of about","options":["1.0","2.1","3.0","4.0"],"answer_index":3,"explanation":"χ(F) = 4.0 is the reference maximum on the Pauling scale.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electronegativity"},{"id":"che-pe-214","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Electronegativity of representative elements generally increases from left to right across a","options":["group","period","lanthanoid row only","set of isotopes"],"answer_index":1,"explanation":"Zeff rises and size falls, so the bonded atom pulls the shared pair more strongly.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electronegativity"},{"id":"che-pe-215","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Electronegativity of representative elements generally decreases from top to bottom in a","options":["period","group","isoelectronic anion pair","triad of identical mass"],"answer_index":1,"explanation":"The bonding electrons are farther from the nucleus in the heavier congener.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electronegativity"},{"id":"che-pe-216","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Among the alkali metals, the member with a particularly low electronegativity is","options":["lithium","sodium","caesium","beryllium"],"answer_index":2,"explanation":"Cs is large and weakly attracting; it is one of the most electropositive metals.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electronegativity"},{"id":"che-pe-217","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Electronegativity is a bonding property of an atom in a molecule, not an isolated-atom energy like","options":["atomic number","ionisation enthalpy","mass number","neutron count"],"answer_index":1,"explanation":"IE and electron gain enthalpy refer to gaseous atoms or ions; χ is defined for an atom already in a bond.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electronegativity"},{"id":"che-pe-218","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"A large electronegativity difference between two bonded atoms favours","options":["pure covalent character","ionic character","metallic bonding only","no bond at all"],"answer_index":1,"explanation":"The shared pair is strongly displaced toward the more electronegative atom, approaching ion formation.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electronegativity"},{"id":"che-pe-219","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"After fluorine, the next most electronegative element is","options":["chlorine","oxygen","nitrogen","neon"],"answer_index":1,"explanation":"Pauling values: F (4.0) > O (3.5) > N ≈ Cl (about 3.0).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electronegativity"},{"id":"che-pe-220","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Metals are characterised by low electronegativity values compared with","options":["noble-gas cores","non-metals","their own cations only","neutrons"],"answer_index":1,"explanation":"Low χ and low IE together describe the electropositive, electron-losing behaviour of metals.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electronegativity"},{"id":"che-pe-221","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Electronegativity falls in the order N > P > As because","options":["atomic size increases down group 15","nuclear charge falls down the group","they become alkali metals","the number of valence electrons decreases"],"answer_index":0,"explanation":"The bonded pair is held farther from the nucleus in the larger P and As atoms.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electronegativity"},{"id":"che-pe-222","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"In period 2 the electronegativity order is","options":["F < O < N < C","C < N < O < F","N < C < F < O","O < C < N < F"],"answer_index":1,"explanation":"χ rises steadily across the period as Zeff increases and radius falls.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electronegativity"},{"id":"che-pe-223","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Fluorine is more electronegative than chlorine, bromine and iodine because of its","options":["larger size and lower Zeff","small size and high effective nuclear charge","half-filled 3d subshell","metallic character"],"answer_index":1,"explanation":"The shared pair in an F–X bond sits closest to a compact, highly charged fluorine atom.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electronegativity"},{"id":"che-pe-224","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"On the Mulliken scale, electronegativity is taken as the average of","options":["atomic radius and density","ionisation enthalpy and electron gain enthalpy (in suitable units)","mass number and atomic number","melting point and boiling point"],"answer_index":1,"explanation":"Mulliken wrote χ ∝ (IE + EA)/2, combining the two isolated-atom energies that measure electron holding and accepting.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electronegativity"},{"id":"che-pe-225","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The H–F bond is more polar than the H–Cl bond because fluorine is","options":["less electronegative than chlorine","more electronegative than chlorine","larger than chlorine","a metal"],"answer_index":1,"explanation":"The greater χ(F) − χ(H) gap displaces the shared pair more strongly toward fluorine.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electronegativity"},{"id":"che-pe-226","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Fluorine outranks chlorine in electronegativity even though Cl has more protons, because the bonding pair in an F–X bond is","options":["farther from the F nucleus","much closer to the small, poorly shielded fluorine atom","held only by London forces","shared equally in every case"],"answer_index":1,"explanation":"Size and Zeff on the valence shell dominate χ; the extra protons of Cl are offset by an extra shielding shell.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"electronegativity"},{"id":"che-pe-227","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Valence electrons of an atom are those present in its","options":["innermost shell","outermost shell","nucleus","neutron cloud"],"answer_index":1,"explanation":"Chemical valence is decided by the electrons in the highest principal shell.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"valence-ox-states"}]$bank$::jsonb) as t(id text, chapter_id text, subject_id text, stem text, options jsonb, answer_index int, explanation text, images jsonb, source jsonb, difficulty text, concept_id text) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
